{
  "name": "本地/远程文件与命令客户端",
  "name_en": "Local/Remote File and Command Client",
  "manufacturer": "",
  "description": "这不是特定的物理仪器，而是实验室自动化中用于访问本地或远程控制计算机的软件客户端，可进行文件上传、下载准备、文件下载以及命令执行，常用于部署实验脚本、传输数据和触发控制任务。",
  "description_en": "This is not a specific physical instrument but a software client used in laboratory automation to access a local or remote control computer. It supports file upload, download preparation, file retrieval, and command execution, and is commonly used to deploy experiment scripts, transfer data, and trigger control tasks.",
  "tag_hints": [
    "file transfer",
    "command execution",
    "lab control computer",
    "automation scripting",
    "remote host access"
  ],
  "actions": [
    {
      "action_name": "auto-upload",
      "description": "上传文件到本地或远程控制端。",
      "description_en": "Upload a file to the local or remote control host."
    },
    {
      "action_name": "auto-prepare_download",
      "description": "准备从本地或远程控制端下载指定文件。",
      "description_en": "Prepare a specified file for download from the local or remote control host."
    },
    {
      "action_name": "auto-download",
      "description": "下载已准备好的文件。",
      "description_en": "Download the file that was previously prepared."
    },
    {
      "action_name": "auto-run_command",
      "description": "在本地或远程控制端执行命令。",
      "description_en": "Execute a command on the local or remote control host."
    }
  ]
}

